package com.smartagri.service; import com.smartagri.model.Models.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class AnalysisService { public AnalysisResponse analyze(AnalysisRequest r){String soil=r.soilType()==null?"unknown":r.soilType().toLowerCase();String farm=r.farmType()==null?"seed":r.farmType().toLowerCase();List<String> rec=new ArrayList<>();if(soil.contains("sandy"))rec.addAll(List.of("Groundnut","Millet","Watermelon","Cowpea"));else if(soil.contains("clay"))rec.addAll(List.of("Rice","Sugarcane","Banana","Taro"));else if(soil.contains("loam"))rec.addAll(List.of("Tomato","Chilli","Cotton","Vegetables","Pulses"));else rec.addAll(List.of("Millet","Pulses","Vegetables"));String advice=switch(farm){case "animal"->"Use Animal Farm for feed, warning signs and prevention. Medicine needs a veterinarian.";case "plant"->"Use Plant Hub for crop care, disease warning signs and harvesting.";default->"Use Seed Centre for seed details, sowing and harvest guidance.";};return new AnalysisResponse(r.soilType(),r.farmType(),rec,advice);}}
